    def default_sentence_texts(content: Any) -> list[str]:
        """Split on terminal punctuation; inaccurate for abbreviations and source spans."""
        import re

        return [sentence for sentence in re.split('(?<=[.!?])\\s+', content) if sentence.strip()]
